// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(amount > 0 && amount < address(c).balance + 1 ether);

        // fund actor and deposit into c via the fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);

        // adversarial callee: reverts whenever it receives value (as C does in P)
        Attacker att = new Attacker();

        // pre-state: actor's balance is funded
        assertTrue(c.balances(actor) == amount);

        // route withdraw's external call through the attacker by making the
        // actor's address the attacker? Not possible; instead prank the attacker's
        // funded account: fund the attacker through fallback, then withdraw from it.
        vm.deal(address(att), amount);
        vm.prank(address(att));
        (bool okDep2, ) = address(c).call{value: amount}("");
        assertTrue(okDep2);

        vm.prank(address(att));
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // Rule: after withdraw, either it reverted (caller keeps its balance)
        // or it succeeded and the balance became zero with the full amount sent.
        // In P, the call to a value-reverting callee carries value>0, reverts,
        // and balances(attacker) stays == amount. In M, the zeroed balance makes
        // C send value 0, the callee accepts, withdraw succeeds, balance == 0.
        assertTrue(c.balances(address(att)) != 0 || !ok);
    }
}

contract Attacker {
    fallback() external payable {
        if (msg.value > 0) revert();
    }
}
